import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shortcuts.md","filePath":"guide/shortcuts.md","lastUpdated":1793128542000}'),s={name:"guide/shortcuts.md"};function h(n,e,i,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>This page lists MeetCue&#39;s global shortcuts and shows how to change them. The shortcuts work while your meeting app has focus.</p><h2 id="default-shortcuts" tabindex="-1">Default shortcuts <a class="header-anchor" href="#default-shortcuts" aria-label="Permalink to &quot;Default shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Space</code></td><td>Start or pause listening</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>Panel: full → mini bar → hidden</td></tr><tr><td><code>Ctrl+Alt+[</code></td><td>Previous question</td></tr><tr><td><code>Ctrl+Alt+]</code></td><td>Next question (in practice: skip the question)</td></tr><tr><td><code>Ctrl+Alt+Enter</code></td><td>Mark the current question answered</td></tr><tr><td><code>Ctrl+Alt+Shift</code> + arrow keys</td><td>Move the panel up, down, left or right</td></tr><tr><td><code>Ctrl+Alt+Shift+1</code>, <code>2</code>, <code>3</code></td><td>Move the panel to saved spot 1, 2 or 3 (on an empty spot: save where it is now)</td></tr><tr><td><code>Ctrl+Alt+Shift+P</code></td><td>Hide the panel for 6 seconds; press again to bring it back sooner</td></tr><tr><td><code>Ctrl+Alt+Shift+T</code></td><td>Let clicks pass through the panel, or stop them passing through</td></tr></tbody></table><h2 id="move-the-panel" tabindex="-1">Move the panel <a class="header-anchor" href="#move-the-panel" aria-label="Permalink to &quot;Move the panel {#move-the-panel}&quot;">​</a></h2><p>Put the panel right under your camera, so that reading a hint looks like looking at the other participants. Tap <code>Ctrl+Alt+Shift</code> with an arrow key to move the panel a little; hold the keys to keep it moving. Hold two arrows to move diagonally. The panel stays on screen, moves to a neighbouring screen when you push it past the side, and remembers where you left it.</p><h2 id="saved-spots" tabindex="-1">Saved spots <a class="header-anchor" href="#saved-spots" aria-label="Permalink to &quot;Saved spots {#saved-spots}&quot;">​</a></h2><p>Most meetings have two or three good places for the panel: beside a shared screen, under your camera, or in a corner away from other attendees&#39; video. Save each one once and jump between them with a shortcut:</p><ol><li>Put the panel where it hides nothing. Use <strong>Move</strong> on the panel to snap it to an edge or corner, or drag it.</li><li>Press <code>Ctrl+Alt+Shift+1</code>. On an empty spot, the shortcut saves where the panel is now, together with its size and layout (full panel or mini bar).</li><li>Later, press <code>Ctrl+Alt+Shift+1</code> again to bring the panel back there.</li></ol><p><strong>Move › Saved spots</strong> on the panel and <strong>Settings › General › Panel</strong> show the spots and let you replace or forget one.</p><h2 id="reach-what-is-behind-the-panel" tabindex="-1">Reach what is behind the panel <a class="header-anchor" href="#reach-what-is-behind-the-panel" aria-label="Permalink to &quot;Reach what is behind the panel&quot;">​</a></h2><ul><li><code>Ctrl+Alt+Shift+P</code> hides the panel for 6 seconds, long enough to click <strong>Join</strong> or a meeting control behind it. It comes back on its own.</li><li><code>Ctrl+Alt+Shift+T</code> lets clicks pass through the panel: it fades and the mouse reaches the window behind it. Press the shortcut again, or use <strong>Let clicks pass through the panel</strong> in the tray menu, to make the panel clickable again.</li></ul><h2 id="why-these-keys" tabindex="-1">Why these keys <a class="header-anchor" href="#why-these-keys" aria-label="Permalink to &quot;Why these keys&quot;">​</a></h2><p>The defaults avoid shortcuts that are already common on Windows laptops:</p><ul><li>meeting apps that use <code>Ctrl+Shift</code> combinations, such as mute in Teams;</li><li>input methods that use <code>Ctrl+Space</code> or <code>Shift+Space</code>;</li><li>graphics drivers that rotate the screen with <code>Ctrl+Alt</code> plus an arrow key, which is why moving the panel adds <code>Shift</code>;</li><li>chat apps that use <code>Ctrl+Alt+A</code>, <code>Ctrl+Alt+W</code> or <code>Ctrl+Alt+Z</code>;</li><li>function keys, which act as media keys on many laptops.</li></ul><h2 id="change-a-shortcut" tabindex="-1">Change a shortcut <a class="header-anchor" href="#change-a-shortcut" aria-label="Permalink to &quot;Change a shortcut&quot;">​</a></h2><ol><li>Open <strong>Settings › Shortcuts</strong>.</li><li>Click <strong>Change</strong> next to the action.</li><li>Press the new key combination. Press <code>Esc</code> to cancel.</li></ol><p>If another program already uses the combination, the row turns red with <a href="/meetcue/troubleshooting/error-codes#mc-hk-001">MC-HK-001</a>. Choose a different combination. <strong>Restore defaults</strong> brings back the table above.</p><h2 id="when-shortcuts-don-t-reach-meetcue" tabindex="-1">When shortcuts don&#39;t reach MeetCue <a class="header-anchor" href="#when-shortcuts-don-t-reach-meetcue" aria-label="Permalink to &quot;When shortcuts don&#39;t reach MeetCue&quot;">​</a></h2><p>Windows doesn&#39;t deliver shortcuts to MeetCue while the foreground window is a program running as administrator, or a game in exclusive full screen. See <a href="/meetcue/troubleshooting/panel">Shortcuts and the panel</a>.</p>',20)])])}const g=t(s,[["render",h]]);export{p as __pageData,g as default};
